import React from 'react';
import { TableData, TableSortState, ColumnDef } from '.';
export interface TableProps<T extends TableData> {
    /**
     * Column Definition for table header and mapping
     */
    columns: ColumnDef[];
    /**
     * Table Data
     */
    data: T[];
    /**
     * To handle sorting on the columns
     */
    handleSort?: (field: string) => void;
    /**
     * Metadata to handle sort state
     */
    sort?: TableSortState;
    /**
     * To handle loading
     */
    isLoading?: boolean;
    /**
     * Number of skeleton rows for loading
     *
     * @default {3}
     */
    loadingSkeletonRows?: number;
    /**
     * To display empty data message
     */
    emptyDataMessage?: React.ReactElement | string;
    /**
     * Sticky header
     *
     * @default false
     */
    stickyHeader?: boolean;
    /**
     * Controls if error message needs to be shown
     *
     * @default false
     */
    isError?: boolean;
    /**
     * Error message content to be shown for error scenario.
     *
     * @default false
     */
    errorContent?: React.ReactElement | string;
    onRowClick?: (row: any, index: number) => void;
    /**
     * selected
     *
     * @default ''
     */
    selectedRowId?: string | number;
}
/**
 * Data Tables display a set of related information in rows and columns. They allow users to efficiently scan and compare large amounts of data and, optionally, to take action on that data
 *
 * ### Content
 *
 * #### Column Definition and Data
 *
 * The table accepts column definiton to structure the table and data to populate within the table.
 *
 * The key of data should match the field in the column to render the data in the right column
 *
 * ```tsx
 * import * as React from "react";
 * import { Table } from "@walmart-dataventures/shared-components";
 *
 * export default () => {
 *  return (
 *      <Table
 *          columns={[{
 *          columnIndex: 0,
            field: 'id',
            header: 'ID',
            type: 'numeric'
            },
            {
            columnIndex: 1,
            field: 'name',
            header: 'Name',
            type: 'alphanumeric'
            }]}
            data={[{
                id: 1658943,
                name: 'Cesar_ChickenBox'
            },
            {
                id: 1658942,
                name: 'Toothbrushes'
            }]}
            isLoading={false}
        />
 *  )
 * }
 *
 * ```
 *
 * ### Features
 *
 * #### Sorting
 *
 * Sorting can be enabled on individual columns by passing `sort: true` in the column definition
 *
 * Sort State can be managed by passing object with attribute and order to the sort prop and passing a callback funciton in `handleSort` prop
 *
 * Example
 *
 * ```tsx
 * <Table
 *  sort={
            attribute: 'name',
            order: 'ascending',
        }
    handleSort={(attribute: string)=>{//handle sort logic}}
    {...restProps}
    />
 * ```
 *
 * #### Fixed Column
 *
 * Fixed column can be enabled on 1st and last columns when the table has many number of columns and we need to enable scroll
 *
 * `fixedColumn: true` should be passed in the column definition
 *
 * Do not enable fixed column in any other column except 1st and last column
 *
 * #### Column Type - Status
 *
 * When column type is set to status, `getStatusColor` prop can be used to send the status color using the row data
 *
 * #### Column Type - header
 *
 * when cloumn type is set to header, that column's data will be rendered as DataHeader.
 * if we  want to hide column header text, we can pass `showColumnHeader: false` in the column definition
 * we can make this column sticky by setting `fixedColumn: true`
 *
 * #### Column Type - Actions
 *
 * When column type is set to actions, we need to pass a function that returns JSX element to render the element in the cell.
 *
 * Example
 *
 * ```tsx
 * {
        header: 'Name',
        field: 'name',
        type: 'action',
        sort: true,
        fixedColumn: true,
        actionElement: (row) => (
            <Button
                variant="tertiary"
                onClick={() => {
                    alert(row?.name);
                }}
            >
                {row?.name}
            </Button>
        ),
    },
 * ```
 *
 * #### Loading
 *
 * When api is still in pending state, `isLoading` can be set to true to display skeleton as loading indicator.
 * Use `loadingSkeletonRows` depending on the number of skeleton rows required to display
 *
 * Example
 *
 * ```tsx
 * <Table
 *    data=[{},{},{}]
 *    isLoading={true}
 *    loadingSkeletonRows={5}
      {...restProps}
    />
    ```
 *
 *
 * #### Sticky header
 *
 * When the table has large amounts of data, and user needs to scroll, setting `stickyHeader` to 'true' will make the header stick to the top
 *
 * #### No data message
 *
 * When there is no data to be displayed, table can display a message for users by setting `emptyDataMessage` prop
 *
 * #### Header Alignment
 *
 * Header text alignment is restricted to numeric columns only for semantic correctness:
 *
 * - **Numeric columns only**: Can use `alignment` property with 'left' or 'right' values
 * - **Non-numeric columns**: Always left-aligned (alignment property is ignored)
 * - **Default behavior**: Numeric columns default to 'right' alignment for easy value comparison
 *
 * Example
 *
 * ```tsx
 * {
        header: 'Price',
        field: 'price',
        type: 'numeric', // Can be aligned left or right
        alignment: 'right',
    },
    {
        header: 'Quantity',
        field: 'quantity',
        type: 'numeric',
        alignment: 'left', // Numeric column with left alignment
    },
    {
        header: 'Product Name',
        field: 'name',
        type: 'alphanumeric', // Always left-aligned
        // alignment property not allowed here
    }
 * ```
 */
export declare const Table: {
    <T extends TableData>({ columns, handleSort, sort, data, isLoading, loadingSkeletonRows, emptyDataMessage, stickyHeader, isError, errorContent, onRowClick, selectedRowId, ...rest }: TableProps<T>): import("react/jsx-runtime").JSX.Element;
    displayName: string;
};
